192	   * the specified file contents.  This method will add a newline terminator to
193	   * the end of the contents string in the destination file.
194	   * @param directory File non-null destination directory.
195	   * @param name String non-null file name.
196	   * @param contents String non-null file contents.
197	   * @throws IOException if an I/O error occurs.
198	   */
199	  private File createFile(File directory, String name, String contents)
200	      throws IOException {
201	    File newFile = new File(directory, name);
202	    PrintWriter pw = new PrintWriter(newFile);
203	    try {
204	      pw.println(contents);
205	    }
206	    finally {
207	      pw.close();
208	    }
209	    return newFile;
210	  }
