479	  /**
480	   * Extend {@link File}. Same as {@link File} except for two things: (1) This
481	   * treats file1Name as a very special file which is not delete-able
482	   * irrespective of it's parent-dir's permissions, a peculiar file instance for
483	   * testing. (2) It returns the files in alphabetically sorted order when
484	   * listed.
485	   * 
486	   */
487	  public static class MyFile extends File {
488	
489	    private static final long serialVersionUID = 1L;
490	
491	    public MyFile(File f) {
492	      super(f.getAbsolutePath());
493	    }
494	
495	    public MyFile(File parent, String child) {
496	      super(parent, child);
497	    }
498	
499	    /**
500	     * Same as {@link File#delete()} except for file1Name which will never be
501	     * deleted (hard-coded)
502	     */
503	    @Override
504	    public boolean delete() {
505	      LOG.info("Trying to delete myFile " + getAbsolutePath());
506	      boolean bool = false;
507	      if (getName().equals(FILE_1_NAME)) {
508	        bool = false;
509	      } else {
510	        bool = super.delete();
511	      }
512	      if (bool) {
513	        LOG.info("Deleted " + getAbsolutePath() + " successfully");
514	      } else {
515	        LOG.info("Cannot delete " + getAbsolutePath());
516	      }
517	      return bool;
518	    }
519	
520	    /**
521	     * Return the list of files in an alphabetically sorted order
522	     */
523	    @Override
524	    public File[] listFiles() {
525	      final File[] files = super.listFiles();
526	      if (files == null) {
527	         return null;
528	      }
529	      List<File> filesList = Arrays.asList(files);
530	      Collections.sort(filesList);
531	      File[] myFiles = new MyFile[files.length];
532	      int i=0;
533	      for(File f : filesList) {
534	        myFiles[i++] = new MyFile(f);
535	      }
536	      return myFiles;
537	    }
538	  }
