558	  /**
559	   * Test that getDU is able to handle cycles caused due to symbolic links
560	   * and that directory sizes are not added to the final calculated size
561	   * @throws IOException
562	   */
563	  @Test (timeout = 30000)
564	  public void testGetDU() throws Exception {
565	    long du = FileUtil.getDU(testFolder.getRoot());
566	    // Only two files (in partitioned).  Each has 3 characters + system-specific
567	    // line separator.
568	    final long expected = 2 * (3 + System.getProperty("line.separator").length());
569	    Assert.assertEquals(expected, du);
570	    
571	    // target file does not exist:
572	    final File doesNotExist = new File(tmp, "QuickBrownFoxJumpsOverTheLazyDog");
573	    long duDoesNotExist = FileUtil.getDU(doesNotExist);
574	    assertEquals(0, duDoesNotExist);
575	    
576	    // target file is not a directory:
577	    File notADirectory = new File(partitioned, "part-r-00000");
578	    long duNotADirectoryActual = FileUtil.getDU(notADirectory);
579	    long duNotADirectoryExpected = 3 + System.getProperty("line.separator").length();
580	    assertEquals(duNotADirectoryExpected, duNotADirectoryActual);
581	    
582	    try {
583	      // one of target files is not accessible, but the containing directory
584	      // is accessible:
585	      try {
586	        FileUtil.chmod(notADirectory.getAbsolutePath(), "0000");
587	      } catch (InterruptedException ie) {
588	        // should never happen since that method never throws InterruptedException.      
589	        assertNull(ie);  
590	      }
591	      assertFalse(FileUtil.canRead(notADirectory));
592	      final long du3 = FileUtil.getDU(partitioned);
593	      assertEquals(expected, du3);
594	
595	      // some target files and containing directory are not accessible:
596	      try {
597	        FileUtil.chmod(partitioned.getAbsolutePath(), "0000");
598	      } catch (InterruptedException ie) {
599	        // should never happen since that method never throws InterruptedException.      
600	        assertNull(ie);  
601	      }
602	      assertFalse(FileUtil.canRead(partitioned));
603	      final long du4 = FileUtil.getDU(partitioned);
604	      assertEquals(0, du4);
605	    } finally {
606	      // Restore the permissions so that we can delete the folder 
607	      // in @After method:
608	      FileUtil.chmod(partitioned.getAbsolutePath(), "0777", true/*recursive*/);
609	    }
610	  }
