612	  @Test (timeout = 30000)
613	  public void testUnTar() throws IOException {
614	    // make a simple tar:
615	    final File simpleTar = new File(del, FILE);
616	    OutputStream os = new FileOutputStream(simpleTar); 
617	    TarOutputStream tos = new TarOutputStream(os);
618	    try {
619	      TarEntry te = new TarEntry("/bar/foo");
620	      byte[] data = "some-content".getBytes("UTF-8");
621	      te.setSize(data.length);
622	      tos.putNextEntry(te);
623	      tos.write(data);
624	      tos.closeEntry();
625	      tos.flush();
626	      tos.finish();
627	    } finally {
628	      tos.close();
629	    }
630	
631	    // successfully untar it into an existing dir:
632	    FileUtil.unTar(simpleTar, tmp);
633	    // check result:
634	    assertTrue(new File(tmp, "/bar/foo").exists());
635	    assertEquals(12, new File(tmp, "/bar/foo").length());
636	    
637	    final File regularFile = new File(tmp, "QuickBrownFoxJumpsOverTheLazyDog");
638	    regularFile.createNewFile();
