1331	  @Test(timeout = 8000)
1332	  public void testCreateSymbolicLinkUsingJava() throws IOException {
1333	    final File simpleTar = new File(del, FILE);
1334	    OutputStream os = new FileOutputStream(simpleTar);
1335	    TarArchiveOutputStream tos = new TarArchiveOutputStream(os);
1336	    File untarFile = null;
1337	    try {
1338	      // Files to tar
1339	      final String tmpDir = "tmp/test";
1340	      File tmpDir1 = new File(tmpDir, "dir1/");
1341	      File tmpDir2 = new File(tmpDir, "dir2/");
1342	      // Delete the directories if they already exist
1343	      tmpDir1.mkdirs();
1344	      tmpDir2.mkdirs();
1345	
1346	      java.nio.file.Path symLink = FileSystems
1347	          .getDefault().getPath(tmpDir1.getPath() + "/sl");
1348	
1349	      // Create Symbolic Link
1350	      Files.createSymbolicLink(symLink,
1351	          FileSystems.getDefault().getPath(tmpDir2.getPath())).toString();
1352	      assertTrue(Files.isSymbolicLink(symLink.toAbsolutePath()));
1353	      // put entries in tar file
1354	      putEntriesInTar(tos, tmpDir1.getParentFile());
1355	      tos.close();
1356	
1357	      untarFile = new File(tmpDir, "2");
1358	      // Untar using java
1359	      FileUtil.unTarUsingJava(simpleTar, untarFile, false);
1360	
1361	      // Check symbolic link and other directories are there in untar file
1362	      assertTrue(Files.exists(untarFile.toPath()));
1363	      assertTrue(Files.exists(FileSystems.getDefault().getPath(untarFile
1364	          .getPath(), tmpDir)));
1365	      assertTrue(Files.isSymbolicLink(FileSystems.getDefault().getPath(untarFile
1366	          .getPath().toString(), symLink.toString())));
1367	
1368	    } finally {
1369	      FileUtils.deleteDirectory(new File("tmp"));
1370	      tos.close();
1371	    }
1372	
1373	  }
