1375	  private void putEntriesInTar(TarArchiveOutputStream tos, File f)
1376	      throws IOException {
1377	    if (Files.isSymbolicLink(f.toPath())) {
1378	      TarArchiveEntry tarEntry = new TarArchiveEntry(f.getPath(),
1379	          TarArchiveEntry.LF_SYMLINK);
1380	      tarEntry.setLinkName(Files.readSymbolicLink(f.toPath()).toString());
1381	      tos.putArchiveEntry(tarEntry);
1382	      tos.closeArchiveEntry();
1383	      return;
1384	    }
1385	
1386	    if (f.isDirectory()) {
1387	      tos.putArchiveEntry(new TarArchiveEntry(f));
1388	      tos.closeArchiveEntry();
1389	      for (File child : f.listFiles()) {
1390	        putEntriesInTar(tos, child);
1391	      }
1392	    }
1393	
1394	    if (f.isFile()) {
1395	      tos.putArchiveEntry(new TarArchiveEntry(f));
1396	      BufferedInputStream origin = new BufferedInputStream(
1397	          new FileInputStream(f));
1398	      int count;
1399	      byte[] data = new byte[2048];
1400	      while ((count = origin.read(data)) != -1) {
1401	        tos.write(data, 0, count);
1402	      }
1403	      tos.flush();
1404	      tos.closeArchiveEntry();
1405	      origin.close();
1406	    }
1407	  }
